/** Real browser rendering; responses generated by actual bounded Python readers.
 * Regenerate data using sandbox/tests/geo_czi_browser_payloads.py with the locked
 * Zeiss CZI library. Only synthetic data; no listener or production API involved.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const data = JSON.parse(readFileSync(new URL('./batch-two-geo-data.json', import.meta.url), 'utf8'));
let ascRequests = [], cziRequests = [];
const canvasReady = page => page.waitForFunction(() => {
  const canvas = document.querySelector('.ol-layer canvas');
  if (!canvas?.width || !canvas?.height) return false;
  const rgba = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height).data;
  return rgba.some((value, i) => i % 4 === 3 && value > 0);
});
async function rasterPixels(page) {
  return page.locator('.ol-layer canvas').first().evaluate(canvas => {
    const context = canvas.getContext('2d'), rgba = context.getImageData(0, 0, canvas.width, canvas.height).data;
    let left = canvas.width, right = -1, top = canvas.height, bottom = -1, pixels = 0;
    for (let index = 3; index < rgba.length; index += 4) if (rgba[index]) { const x = (index - 3) / 4 % canvas.width, y = Math.floor((index - 3) / 4 / canvas.width); left = Math.min(left, x); right = Math.max(right, x); top = Math.min(top, y); bottom = Math.max(bottom, y); pixels++; }
    const cell = (x, y) => Array.from(context.getImageData(Math.floor(left + (right - left + 1) * (x + 0.5) / 4), Math.floor(top + (bottom - top + 1) * (y + 0.5) / 3), 1, 1).data);
    return { pixels, topLeft: cell(0, 0), bottomLeft: cell(0, 2), missing: cell(1, 1) };
  });
}
export const batchTwoGeoCases = [
  { name: 'batch-two-asc', component: 'GeoFormatPreview.vue', filename: 'synthetic.asc', reader: 'geoformat', descriptor: { adapter: 'geoscience-formats' },
    init: async () => { ascRequests = []; },
    preview: request => { ascRequests.push(request); assert.equal(request.kind, 'map'); if (request.options.crs) { assert.equal(request.options.crs, 'EPSG:4326'); assert.equal(request.version, '1'.repeat(64)); return data.asc_wgs84; } assert.deepEqual(request.options, {}); return data.asc; },
    ready: async page => { await page.getByText(/最近邻预览.*纯数值热图/).waitFor(); await canvasReady(page); },
    verify: async page => {
      const before = await rasterPixels(page); assert.ok(before.pixels > 1000); assert.deepEqual(before.topLeft, [0, 190, 255, 255]); assert.equal(before.missing[3], 0);
      await page.getByRole('combobox').selectOption('EPSG:4326'); await page.getByRole('button', { name: '应用坐标系' }).click();
      await page.getByText('4×3 最近邻预览 · EPSG:4326', { exact: false }).waitFor(); await canvasReady(page);
      assert.equal(ascRequests.length, 2); const after = await rasterPixels(page); assert.deepEqual(after.topLeft, before.topLeft); assert.equal(after.missing[3], 0);
      assert.equal(await page.evaluate(() => window.__activeBlobs.size), 1); return { unknownCrsNotInferred: true, explicitWgs84: true, versionPinned: true, requests: ascRequests.length, nativeCanvas: after };
    } },
  { name: 'batch-two-grd', component: 'GeoFormatPreview.vue', filename: 'synthetic.grd', reader: 'geoformat', descriptor: { adapter: 'geoscience-formats' }, preview: data.grd,
    ready: canvasReady, verify: async page => {
      const pixels = await rasterPixels(page); assert.deepEqual(pixels.bottomLeft, [0, 190, 255, 255]); assert.ok(pixels.topLeft[0] > pixels.topLeft[2]); assert.equal(pixels.missing[3], 0);
      await page.getByText('网格定位：node', { exact: false }).waitFor(); return { actualDsaaReaderOutput: true, northSouthCorrect: true, nodeHalfCellExtent: data.grd.metadata.extent, nativeCanvas: pixels };
    } },
  { name: 'batch-two-kml', component: 'GeoFormatPreview.vue', filename: 'synthetic.kml', reader: 'geoformat', descriptor: { adapter: 'geoscience-formats' }, preview: data.kml,
    ready: canvasReady, verify: async page => {
      await page.getByText('3 个要素 · WGS84', { exact: false }).waitFor(); assert.equal(await page.getByRole('combobox').count(), 0);
      const drawing = await rasterPixels(page); assert.ok(drawing.pixels > 500); return { actualRestrictedKmlReaderOutput: true, geometryTypes: ['Point', 'LineString', 'Polygon'], nativeCanvasPixels: drawing.pixels, noCrsOverride: true };
    } },
  { name: 'batch-two-czi', component: 'CziPreview.vue', filename: 'synthetic.czi', reader: 'czi', descriptor: { adapter: 'czi-image' }, file: { size: data.provenance.czi_bytes },
    init: async () => { cziRequests = []; },
    preview: request => {
      cziRequests.push(request);
      if (request.kind === 'tree') { assert.deepEqual(request.options, {}); return data.czi_tree; }
      assert.equal(request.kind, 'image'); assert.equal(request.version, '1'.repeat(64)); assert.deepEqual(request.options, { indices: [1, 1, 0], roi: [2, 1, 3, 2] }); return data.czi_image;
    },
    ready: page => page.getByText('结构已读取；图像像素尚未读取', { exact: false }).waitFor(),
    verify: async page => {
      assert.equal(cziRequests.length, 1); assert.equal(await page.locator('img').getAttribute('src'), null);
      await page.getByRole('combobox').selectOption('1');
      for (const [label, value] of [['Z 层', '1'], ['时间 T', '0'], ['ROI X', '2'], ['ROI Y', '1'], ['宽度', '3'], ['高度', '2']]) await page.getByLabel(label, { exact: true }).fill(value);
      await page.getByRole('button', { name: '读取所选平面' }).click();
      await page.waitForFunction(() => { const image = document.querySelector('img'); return image.complete && image.naturalWidth === 3 && image.naturalHeight === 2; });
      const pixels = await page.locator('img').evaluate(image => { const canvas = document.createElement('canvas'); canvas.width = 3; canvas.height = 2; const context = canvas.getContext('2d'); context.drawImage(image, 0, 0); const first = Array.from(context.getImageData(0, 0, 1, 1).data), last = Array.from(context.getImageData(2, 1, 1, 1).data); canvas.width = 0; canvas.height = 0; return { first, last }; });
      assert.deepEqual(pixels.first, [0, 0, 0, 255]); assert.deepEqual(pixels.last, [255, 255, 255, 255]); assert.equal(cziRequests.length, 2);
      const display = await page.locator('img').boundingBox(); assert.ok(display.width >= 128 && display.height >= 64, 'Small ROI must remain visibly inspectable without changing native pixels');
      await page.getByText('1110, 1120', { exact: false }).waitFor(); return { nativeZeissReaderSource: data.provenance, explicitCZTRoi: true, versionPinned: true, realPngDecode: pixels, visibleRoiDisplay: display, requests: cziRequests.length };
    }, beforeUnmount: page => page.evaluate(() => { window.__heldCziImage = document.querySelector('img'); }),
    verifyCleanup: async page => { const removed = await page.evaluate(() => !window.__heldCziImage.hasAttribute('src')); assert.equal(removed, true); return { imageSourceRemoved: removed }; } },
];
